// Core App State Architecture
let appState = {
    isAuthenticated: false,
    currentUser: null,
    currentChannel: null,
    searchHistory: [],
    pendingUser: null
};

// Initialize Navigation and Interface Layout states on load
document.addEventListener('DOMContentLoaded', () => {
    loadHistoryFromStorage();
    refreshApplicationView();
});

function refreshApplicationView() {
    const mainNav = document.getElementById('mainNav');
    const publicView = document.getElementById('publicView');
    const portalView = document.getElementById('portalView');
    
    if (appState.isAuthenticated) {
        // Render Authenticated Navigation layout components
        mainNav.innerHTML = `
            <span class="user-tag">👤 Account: <strong>${appState.currentUser.name}</strong></span>
            <a href="#" onclick="logoutSession()">Log Out Securely</a>
        `;
        // Transition Page Views
        publicView.classList.add('hidden');
        portalView.classList.remove('hidden');
        document.getElementById('userGreeting').innerText = `Welcome back, ${appState.currentUser.name}`;
        
        // Check for active update flags on active logs
        evaluateTelemetryAlerts();
        renderHistoryLog();
    } else {
        // Render Public Navigation configuration
        mainNav.innerHTML = `
            <a href="#" onclick="showAuthModal('login')">Access Portal</a>
            <button class="btn btn-primary" onclick="showAuthModal('signup')">Sign Up Free</button>
        `;
        publicView.classList.remove('hidden');
        portalView.classList.add('hidden');
        document.getElementById('telemetryAlert').classList.add('hidden');
    }
}

// Authentication Flow Layer Interventions
function showAuthModal(view) {
    document.getElementById('authModal').classList.remove('hidden');
    switchAuthView(view);
}

function closeAuthModal() {
    document.getElementById('authModal').classList.add('hidden');
}

function switchAuthView(view) {
    document.getElementById('authRegisterView').classList.add('hidden');
    document.getElementById('authLoginView').classList.add('hidden');
    document.getElementById('authChallengeView').classList.add('hidden');
    
    if (view === 'signup') {
        document.getElementById('authRegisterView').classList.remove('hidden');
    } else if (view === 'login') {
        document.getElementById('authLoginView').classList.remove('hidden');
    } else if (view === 'challenge') {
        document.getElementById('authChallengeView').classList.remove('hidden');
    }
}

function toggleAuthFields() {
    const channel = document.getElementById('regChannel').value;
    if (channel === 'email') {
        document.getElementById('emailFieldWrapper').classList.remove('hidden');
        document.getElementById('phoneFieldWrapper').classList.add('hidden');
    } else {
        document.getElementById('emailFieldWrapper').classList.add('hidden');
        document.getElementById('phoneFieldWrapper').classList.remove('hidden');
    }
}

function toggleLoginFields() {
    const channel = document.getElementById('loginChannel').value;
    if (channel === 'email') {
        document.getElementById('loginEmailWrapper').classList.remove('hidden');
        document.getElementById('loginPhoneWrapper').classList.add('hidden');
    } else {
        document.getElementById('loginEmailWrapper').classList.add('hidden');
        document.getElementById('loginPhoneWrapper').classList.remove('hidden');
    }
}

// Handle Registration Data Inputs
function handleRegistration(event) {
    event.preventDefault();
    const name = document.getElementById('regName').value;
    const channel = document.getElementById('regChannel').value;
    const identifier = (channel === 'email') ? document.getElementById('regEmail').value : document.getElementById('regPhone').value;
    
    if (!identifier) return alert('Please supply a valid communication endpoint.');
    
    appState.pendingUser = { name, channel, identifier };
    document.getElementById('challengeSubtitle').innerText = `A 6-digit verification code has been dispatched to: ${identifier}`;
    switchAuthView('challenge');
}

// Handle Login Requests
function handleLoginSubmit(event) {
    event.preventDefault();
    const channel = document.getElementById('loginChannel').value;
    const identifier = (channel === 'email') ? document.getElementById('loginEmail').value : document.getElementById('loginPhone').value;
    
    if (!identifier) return alert('Please supply registered identifier.');
    
    appState.pendingUser = { name: "Ayabongwa Sphesihle", channel, identifier }; // Fallback contextual match parameter
    document.getElementById('challengeSubtitle').innerText = `A fresh login validation key was sent to: ${identifier}`;
    switchAuthView('challenge');
}

// Verification Challenge Core Logic
function verifyChallengeCode(event) {
    event.preventDefault();
    const code = document.getElementById('challengeCode').value;
    
    if (code.length === 6) {
        appState.isAuthenticated = true;
        appState.currentUser = appState.pendingUser;
        appState.pendingUser = null;
        closeAuthModal();
        refreshApplicationView();
    } else {
        alert('Invalid cryptographic token sequence entered.');
    }
}

function logoutSession() {
    appState.isAuthenticated = false;
    appState.currentUser = null;
    refreshApplicationView();
}

// Risk Computation Engine
function executeAnalysis() {
    const industry = document.getElementById('industrySelect').value;
    const company = document.getElementById('companyInput').value;
    const country = document.getElementById('countryInput').value || "Global Scale";
    const depth = document.querySelector('input[name="reportDepth"]:checked').value;
    
    let baseData = industryData[industry][depth];
    
    // Inject Custom Corporate Risk Profiles if variables exist
    if (company.trim() !== "") {
        const corporatePrefix = `<p><strong>🚨 HIGH-PRIORITY CORPORATE RISK MAP INJECTED FOR: "${company.trim().toUpperCase()}" (${country})</strong><br>
        Background analytics matrix profiles specific parameters at structural operational levels for ${company.trim()}. Systems engineering layers demonstrate vulnerability vectors adapting to direct automation interfaces. Local corporate oversight matrices should monitor the following generated dataset closely.</p>`;
        baseData = corporatePrefix + baseData;
    } else if (country !== "Global Scale") {
        const countryPrefix = `<p><strong>🌍 REGIONAL ARCHITECTURAL ANALYSIS MATRIX OUT-TURN: JURISDICTION - ${country.toUpperCase()}</strong><br>
        National legal boundaries and territorial labor distribution models alter baseline automated tracking arrays. This localized readout incorporates structural parameters tracking country automation indexes.</p>`;
        baseData = countryPrefix + baseData;
    }
    
    // Set presentation elements
    document.getElementById('outputTitle').innerText = document.getElementById('industrySelect').options[document.getElementById('industrySelect').selectedIndex].text.split(',')[0];
    document.getElementById('outputContextTag').innerText = company ? company : country;
    document.getElementById('outputDepthTag').innerText = depth === 'summary' ? 'Summary (1300+ Words)' : 'Deep Research (2500+ Words)';
    
    document.getElementById('outputTextDisplay').innerHTML = baseData;
    document.getElementById('analyticsOutput').classList.remove('hidden');
    
    // Smooth Focus Scroll down to output matrix block
    document.getElementById('analyticsOutput').scrollIntoView({ behavior: 'smooth' });
    
    // Log parameters to workspace logs
    logHistoryEntry(industry, company || "General Spectrum", country, depth);
}

// Search History State Framework Logs
function logHistoryEntry(industry, company, country, depth) {
    const entry = {
        id: Date.now(),
        industryName: document.getElementById('industrySelect').options[document.getElementById('industrySelect').selectedIndex].text.split(',')[0],
        company,
        country,
        depth,
        timestamp: new Date().toLocaleString()
    };
    
    appState.searchHistory.unshift(entry);
    saveHistoryToStorage();
    renderHistoryLog();
}

function renderHistoryLog() {
    const listElement = document.getElementById('historyLogList');
    const filterText = document.getElementById('historySearchInput').value.toLowerCase();
    
    listElement.innerHTML = "";
    
    const filtered = appState.searchHistory.filter(item => 
        item.industryName.toLowerCase().includes(filterText) || 
        item.company.toLowerCase().includes(filterText) ||
        item.country.toLowerCase().includes(filterText)
    );
    
    if (filtered.length === 0) {
        listElement.innerHTML = `<p class="panel-desc" style="text-align:center; padding: 20px 0;">No matching log rows retained inside this session.</p>`;
        return;
    }
    
    filtered.forEach(item => {
        const row = document.createElement('div');
        row.className = "history-row";
        row.innerHTML = `
            <div class="history-meta">
                <h4>${item.industryName} <span style="font-size:11px; font-weight:normal; color:var(--color-accent);">(${item.depth.toUpperCase()})</span></h4>
                <p>Scope: <strong>${item.company}</strong> (${item.country}) — ${item.timestamp}</p>
            </div>
            <button class="btn btn-text" onclick="deleteHistoryItem(${item.id})">Purge Entry 🗑️</button>
        `;
        listElement.appendChild(row);
    });
}

function deleteHistoryItem(id) {
    appState.searchHistory = appState.searchHistory.filter(item => item.id !== id);
    saveHistoryToStorage();
    renderHistoryLog();
}

function clearAllHistory() {
    if(confirm("Confirm security erasure of all retention logs?")) {
        appState.searchHistory = [];
        saveHistoryToStorage();
        renderHistoryLog();
    }
}

function saveHistoryToStorage() {
    localStorage.setItem('futurehub_history_logs', JSON.stringify(appState.searchHistory));
}

function loadHistoryFromStorage() {
    const stored = localStorage.getItem('futurehub_history_logs');
    if (stored) {
        appState.searchHistory = JSON.parse(stored);
    }
}

function evaluateTelemetryAlerts() {
    if (appState.searchHistory.length > 0) {
        document.getElementById('telemetryAlert').classList.remove('hidden');
        document.getElementById('alertMessage').innerText = `Automated notification for ${appState.currentUser.name}: Fresh automation tracking alerts have logged matching your historical query framework.`;
    } else {
        document.getElementById('telemetryAlert').classList.add('hidden');
    }
}
